package APEMemory {
    private import ScalarValues::*;

    doc /* APE 5.2 - Governed Memory Promotion. Bounded local-note mechanisms
     * promote observations to reusable guidance through an
     * exact revision and digest decision. Capturing or reading a candidate does
     * not admit it. A policy belongs directly to one ConversationSystem and its
     * builder owns the local memory. Each action additionally requires an exact
     * native BehaviorAccess; this declaration alone grants no permission. */

    part def GovernedMemoryPolicy {
        attribute id : String;
        attribute revision : Integer {
            doc /* Positive safe integer. Every instantiated field is required. */
        }
        attribute allowedScopes : String {
            doc /* JSON text containing an explicit array of 1 to 32 distinct,
             * nonempty scope names. No global or cross-operator scope is added
             * implicitly. These labels classify local guidance only. */
        }
        attribute requireSourceRefs : Boolean;
        attribute requireKnownOutcome : Boolean;
        attribute maxValidityMs : Integer {
            doc /* Inclusive supported range: 1 to 31536000000 milliseconds.
             * Expiration does not renew automatically on recall or restart. */
        }
        attribute allowSelfAdmission : Boolean;
    }

    item def CaptureMemoryRequest {
        attribute id : String;
        attribute contentJson : String {
            doc /* JSON text containing exactly these required fields:
             * text: nonempty proposed guidance, at most 65536 characters;
             * origin: {decisionId: exact originating decision id,
             *          sourceRefs: array of local evidence references};
             * scope: nonempty array of explicit allowed scope names;
             * validUntil: explicit validity deadline as a timestamp string;
             * outcome: {status: "pending"} while the result is unknown, or
             *          {status: "known", summary: nonempty observed result,
             *           evidenceRefs: nonempty array of local evidence references}.
             * Source and outcome references use message:<exact local message id>.
             * Use observed local ids, never invented or peer references. The
             * host checks provenance, scopes, deadline and the admitted policy.
             * Capturing creates a candidate, never admitted guidance. */
        }
    }
    item def RecallMemoryRequest {
        attribute id : String [0..1];
    }
    item def ReviseMemoryRequest {
        attribute id : String;
        attribute expectedRevision : Integer;
        attribute expectedDigest : String;
        attribute contentJson : String {
            doc /* Complete replacement content using exactly the same JSON
             * shape as CaptureMemoryRequest.contentJson: text, origin with
             * decisionId and sourceRefs, scope, validUntil, and outcome. Outcome
             * is {status: "pending"} or {status: "known", summary, evidenceRefs}.
             * References use message:<exact local message id>. Revision requires
             * the current expectedRevision and expectedDigest and does not
             * inherit admission of the previous content. */
        }
    }
    item def ReviewMemoryRequest {
        attribute id : String;
        attribute expectedRevision : Integer;
        attribute expectedDigest : String;
        attribute decision : String {
            doc /* Exact decision: admit, request-revision or reject. The host
             * validates current authority, revision, digest and evidence.
             * Admission may additionally require source references and a known
             * outcome. Neither request-revision nor reject admits the content. */
        }
        attribute reason : String;
    }
    item def WithdrawMemoryRequest {
        attribute id : String;
        attribute expectedRevision : Integer;
        attribute expectedDigest : String;
        attribute reason : String;
    }

    action def CaptureMemory {
        in request : CaptureMemoryRequest;
    }
    action def RecallMemory {
        in request : RecallMemoryRequest;
    }
    action def ReviseMemory {
        in request : ReviseMemoryRequest;
    }
    action def ReviewMemory {
        in request : ReviewMemoryRequest;
    }
    action def WithdrawMemory {
        in request : WithdrawMemoryRequest;
    }
}

sources.skills.sysml:
package APESkills {
    private import ScalarValues::*;

    doc /* Skills are versioned local instructions belonging to decision context.
     * Installing text neither executes it nor activates its instructions.
     * Explicit native exposures separately grant installation, listing, loading
     * and unloading; this policy alone grants none of those operations.
     * Classic executable tools retain their independent catalog and lifecycle. */

    part def SkillPolicy {
        attribute id : String;
        attribute revision : Integer;
        attribute allowedHosts : String {
            doc /* JSON array of exact HTTPS DNS hosts allowed for this local
             * instruction downloader. This does not grant classic tool access. */
        }
        attribute maxSkillBytes : Integer;
        attribute maxInstalledSkills : Integer;
        attribute maxLoadedSkills : Integer;
        attribute maxLoadedCharacters : Integer;
    }

    part def InitialSkill {
        attribute id : String;
        attribute source : String;
        attribute digest : String {
            doc /* SHA-256 of the referenced artifact's exact UTF-8 bytes.
             * Sources retain the reference and digest, never the skill body.
             * The bounded bundle resolver verifies those bytes at installation. */
        }
        attribute loaded : Boolean {
            doc /* Initial activation choice under this admitted source version.
             * A persisted later unload must not be reversed on restart. */
        }
    }

    item def InstallSkillRequest {
        attribute id : String;
        attribute url : String;
        attribute expectedDigest : String [0..1];
        doc /* Download one raw UTF-8 SKILL.md from an admitted HTTPS host.
         * No archive extraction, script execution or implicit activation.
         * An optional expectedDigest pins acquisition to known exact bytes. */
    }
    item def ListSkillsRequest;
    item def LoadSkillRequest {
        attribute id : String;
        attribute expectedDigest : String;
        doc /* Select the exact installed version for subsequent decision
         * contexts. Its instructions cannot change the caller's mandate. */
    }
    item def UnloadSkillRequest {
        attribute id : String;
        attribute expectedDigest : String;
    }
    action def InstallSkill { in request : InstallSkillRequest; }
    action def ListSkills { in request : ListSkillsRequest; }
    action def LoadSkill { in request : LoadSkillRequest; }
    action def UnloadSkill { in request : UnloadSkillRequest; }
}

sources.behavior-invocations.sysml:
package ASEInvocations {
    private import ScalarValues::*;
    private import ASECore::*;

    doc /* Explicit source-owned exposure of a performed behavior to an operator.
     * Allocation alone does not authorize invocation. The actual caller and
     * target are fixed by native bindings on each enabled occurrence.
     * Input is a schema reference, refined to a model-owned item definition;
     * it is not a stored request and has no binding to mutable case facts. */

    part def BehaviorAccess {
        attribute name : String;
        attribute description : String;
        attribute enabled : Boolean;
        ref part caller : SoftwareOperator;
        ref action target : Actions::Action;
        ref item input : Items::Item;
    }
}

sources.work-budget.sysml:
package APEWorkBudget {
    private import ScalarValues::*;

    doc /* APE 3.6 - Budget-Bounded Loop. Bounded realization for cumulative
     * agent invocations in one durable operator dossier; not tokens or cost.
     * Definitions alone grant no permission and select no budget. Instantiate
     * exactly one policy directly inside the concrete ConversationSystem.
     * Only an admitted source revision can change this policy. Runtime counters
     * live outside the model and cannot be written by the agent. */

    part def InvocationBudgetPolicy {
        attribute id : String;
        attribute revision : Integer {
            doc /* Positive safe integer, increased by an admitted source edit. */
        }
        attribute unit : String {
            doc /* Exactly "agent-invocation". One unit reserves one invocation
             * of AgentPort.decide, review or admit, including failed calls.
             * This is neither tokens, monetary cost nor actual HTTP calls:
             * a Muse invocation may internally perform three provider steps. */
        }
        attribute limit : Integer {
            doc /* Inclusive range 0 to 1000000, a safe integer. This supported
             * ceiling prevents unbounded operational profiles; it is not a
             * promise of storage capacity or provider quota. Consumption is
             * cumulative across the durable dossier, including source edits. */
        }
        attribute onExhausted : String {
            doc /* Exactly "wait". Exhaustion dispatches no further invocation. */
        }
        attribute exhaustionRecipient : String {
            doc /* Exactly "local-control": the local design/adoption command.
             * This recipient does not prove an authenticated human identity. */
        }
    }
}

sources.work-operators.sysml:
package ASEWork {
    private import ScalarValues::*;

    doc /* Generic technical entries into modeled operator runtimes and their
     * artifact catalogs. A performed occurrence must be allocated to the exact
     * operator or catalog in its owning ConversationSystem. BehaviorAccess
     * separately fixes every authorized caller. These definitions grant no
     * admission, network scope or access to another conversation. */

    item def WorkRequest {
        attribute text : String;
    }
    item def EmptyRequest;
    item def WorkArtifactQuery {
        attribute workInvocationId : String;
        attribute workBehaviorId : String;
        attribute workInputDigest : String;
        attribute artifactName : String;
    }
    action def InspectWorkArtifacts {
        in request : WorkArtifactQuery;
        out result : ASEToolPublicationResult::PublicationObservation;
        doc /* Read source-owned active artifact facts correlated to one exact
         * work invocation. This action grants no construction or admission. */
    }
    item def ReuseToolRequest {
        attribute sourceAgentId : String;
        attribute candidateId : String;
        attribute digest : String;
    }
    action def AgentInbox {
        in request : WorkRequest;
        doc /* The host correlates one admitted request with one operator's
         * own modeled flow. It transmits this request, never peer history. */
    }
    action def ReuseTool {
        in request : ReuseToolRequest;
        doc /* Reuse exact published bytes as a local proposal. Local tests,
         * mandate, admission and activation remain mandatory. */
    }
    action def ListPublishedTools {
        in request : EmptyRequest;
        doc /* Read metadata of exact active artifacts in the same modeled
         * system. Neither source code nor conversations nor rights are copied. */
    }
}

sources.verified-effect-closure.sysml:
package APEVerifiedEffectClosure {
    private import ScalarValues::*;
    private import ASEInvocations::*;

    doc /* APE 3.4: source-owned expected values, observed state type and native
     * constraint. Work and observation remain separately admitted actions.
     * The bounded runtime evaluates scalar items and native constraints; this
     * library does not claim support for native verification-case execution. */
    part def WorkResultContract {
        ref part work : BehaviorAccess;
        ref part observation : BehaviorAccess;
        ref item input : Items::Item [0..1];
        item expected : Items::Item;
        ref item observed : Items::Item;
        item query : Items::Item [0..1];
        constraint condition;
        attribute maxObservations : Integer;
    }
}

