package ASEToolPublicationResult {
    private import ScalarValues::*;
    doc /* Technical publication facts supplied by the allocated catalog reader.
     * Verification criteria belong to the caller's WorkResultContract. */
    item def PublicationExpectation {
        attribute name : String;
        attribute kind : String;
        attribute status : String;
        attribute count : Integer;
    }
    item def PublicationQuery {
        attribute artifactName : String;
    }
    item def PublicationObservation {
        attribute nativeCount : Integer;
        attribute nativeName : String;
        attribute nativeKind : String;
        attribute nativeContractCount : Integer;
        attribute nativeContractKind : String;
        attribute count : Integer;
        attribute name : String;
        attribute kind : String;
        attribute localStatus : String;
        attribute nativeStatus : String;
        attribute storedDigest : String;
        attribute actualDigest : String;
        attribute nativeDigest : String;
        attribute admittedDigest : String;
        attribute admittedCandidateId : String;
        attribute candidateId : String;
        attribute testsPassed : Boolean;
        attribute nativeId : String;
        attribute bindingId : String;
    }
}

sources.model-editing.sysml:
package ASEModelEditing {
    private import ScalarValues::*;
    doc /* APE 4.1 Operator Identity & Mandate: bounded source-editing delegation.
     * Proposals remain subject to 2.1 Proposal–Admission–Execution Separation.
     * This declaration configures permissions; it is not execution evidence. */
    part def ModelEditPolicy {
        ref holder : ASECore::SoftwareOperator;
        ref item mandate : ASECore::ConfiguredMandate;
        attribute id : String;
        attribute revision : Integer;
        attribute operations : String;
        attribute grants : String;
        doc /* Explicit source-admitted editing bounds for the bound holder and
         * current mandate. Operations and file/qualified-root pairs are canonical
         * JSON arrays. Definitions alone grant no editing authority. */
    }
}

sources.model-administration.sysml:
package ASEModelAdministration {
    private import ScalarValues::*;
    doc /* APE 4.1 Operator Identity & Mandate: bounded authority to grant and
     * redelegate source-editing rights. Proposals remain subject to 2.1
     * Proposal–Admission–Execution Separation. This declaration configures
     * permissions; it is not execution evidence. */
    part def ModelAdministrationPolicy {
        ref holder : ASECore::SoftwareOperator;
        ref item mandate : ASECore::ConfiguredMandate;
        attribute id : String;
        attribute revision : Integer;
        attribute operations : String;
        attribute grants : String;
        attribute recipients : String;
        attribute maxRedelegationDepth : Integer;
        doc /* Explicit source-admitted administration bounds for the bound
         * holder and current mandate. Operations, file/qualified-root pairs
         * and exact eligible ConversationSystem qualified names are canonical
         * JSON arrays. Depth is 0..8; zero permits direct editing grants but no
         * further administration grants. Administration grants no editing
         * power by itself. Definitions alone grant no authority. */
    }
}
